WITH fixes(pos,why) AS (VALUES (3,'Correto. No procedimento de tutela cautelar antecedente, o art. 308 do CPC estabelece que o pedido principal seja formulado em 30 dias contados da efetivação da tutela cautelar.'),(5,'Correto. O art. 294 do CPC divide a tutela provisória conforme seu fundamento em tutela de urgência e tutela de evidência.'),(8,'Errado. O art. 295 do CPC dispensa o pagamento de custas adicionais para a tutela provisória requerida incidentalmente.'),(9,'Correto. Pelo art. 296 do CPC, a tutela provisória conserva sua eficácia durante o processo, mas pode ser revogada ou modificada a qualquer tempo.'),(10,'Correto. O art. 297 do CPC autoriza o juiz a determinar medidas que considere adequadas para efetivar a tutela provisória.'),(11,'Correto. O art. 300 do CPC exige probabilidade do direito e perigo de dano ou risco ao resultado útil do processo para a tutela de urgência.'),(12,'Correto. O art. 300, § 2º, do CPC permite conceder tutela de urgência liminarmente ou depois de justificação prévia.'),(13,'Errado. O art. 300, § 3º, do CPC prevê que a tutela de urgência antecipada não será concedida quando houver perigo de irreversibilidade dos efeitos da decisão.'),(14,'Correto. O art. 301 do CPC admite arresto, sequestro, arrolamento de bens e outras medidas idôneas para efetivar a tutela cautelar.'),(15,'Correto. O art. 303 do CPC admite pedido antecedente de tutela antecipada quando a urgência for contemporânea ao ajuizamento da ação.'),(16,'Correto. O art. 304 do CPC prevê estabilização da tutela antecipada antecedente se não houver interposição do recurso cabível, observadas as regras aplicáveis.'),(17,'Errado. O art. 304, § 6º, do CPC afirma expressamente que a decisão que concede tutela antecipada estabilizada não faz coisa julgada material.'),(18,'Correto. O art. 311 do CPC admite tutela de evidência independentemente da demonstração de perigo de dano ou risco ao resultado útil do processo.'),(19,'Correto. O art. 311, I, do CPC permite tutela de evidência quando ficar caracterizado abuso do direito de defesa ou manifesto propósito protelatório.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='processo-civil-tutela-provisoria' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;